gdr.ValidationScript:
/////////////////////////////////////////////////////////////
// Global variables
/////////////////////////////////////////////////////////////
/**
 * Returns all items in PO form by PR number.
 * @returns {object} items map by PR number
 */
function GetPRItemsInForm() {
    var allPRItems = {};
    Sys.Helpers.Data.ForEachTableItem("LineItems__", function (line) {
        var prNumber = line.GetValue("PRNumber__");
        if (!(prNumber in allPRItems)) {
            allPRItems[prNumber] = [];
        }
        allPRItems[prNumber].push(line);
    });
    return allPRItems;
}
function CancelItems() {
    //Notify all PR
    var allPRItems = GetPRItemsInForm(), lockByPRNames = Object.keys(allPRItems), resumeWithActionData;
    // Protect concurrent access on PO items for each PR number
    Process.PreventConcurrentAccess(lockByPRNames, function () {
        Sys.Helpers.Object.ForEach(allPRItems, function (prItems, prNumber) {
            resumeWithActionData = {
                user: {
                    login: Lib.P2P.GetOwner().GetValue("login"),
                    name: Lib.P2P.GetOwner().GetValue("DisplayName"),
                    email: Lib.P2P.GetOwner().GetValue("EmailAddress")
                },
                date: new Date(),
                comment: Data.GetValue("Comment__"),
                lines: []
            };
            Sys.Helpers.Object.ForEach(prItems, function (item /*, i*/) {
                resumeWithActionData.lines.push(item.GetValue("PRLineNumber__"));
                Log.Info("Call Cancel Item for item : " + prNumber + "-" + item.GetValue("PRLineNumber__"));
            });
            Lib.Purchasing.Items.ResumeDocumentToSynchronizeItems("Purchase requisition", prItems[0].GetValue("PRRUIDEX__"), "Cancel_items", JSON.stringify(resumeWithActionData));
        });
    });
}
/////////////////////////////////////////////////////////////
// Main
/////////////////////////////////////////////////////////////
Lib.Purchasing.InitTechnicalFields(false, false);
var currentName = Data.GetActionName();
var currentAction = Data.GetActionType();
Log.Info("-- PRI Validation Script -- Name: '" + (currentName ? currentName : "<empty>") + "', Action: '" + (currentAction ? currentAction : "<empty>") + "'");
if (currentName !== "" && currentAction !== "") {
    if (currentAction === "approve_asynchronous" && currentName === "Cancel_PRItems") {
        CancelItems();
    }
}
//# sourceMappingURL=validationscript.js.map

gdr.ExtractionScript:
// set some values on record
Lib.Purchasing.InitTechnicalFields(false, false);
var ancestorsids = Variable.GetValueAsString("AncestorsRuid").split("|");
var filter = "", options = { resetItems: true, orderByMsn: null };
var i;
for (i = 0; i < ancestorsids.length; i++) {
    if (ancestorsids[i].startsWith("CT#")) {
        // It's a PR item
        var msn = ancestorsids[i].split('.')[1];
        filter += "(MSN=" + msn + ")";
        if (!options.orderByMsn) {
            options.orderByMsn = [];
        }
        options.orderByMsn.push(msn);
    }
}
if (i > 1) {
    filter = "(|" + filter + ")";
}
// only no completely ordered items for this ruidex
Log.Info("Filling PRItems Canceler Form with items from filter: " + filter);
Lib.Purchasing.PRICancelerItems.FillForm(filter, options)
    .Catch(function (e) {
    Lib.CommonDialog.NextAlert.Define("_PRItems Canceler creation error", e, { isError: true, behaviorName: "PRICanclerInitError" });
});
//# sourceMappingURL=extractionscript.js.map

ui.CustomScript:
/* Purchase order HTML page script */
const topMessageWarning = Lib.P2P.TopMessageWarning(Controls.TopPaneWarning, Controls.TopMessageWarning__);
const banner = Sys.Helpers.Banner;
banner.SetHTMLBanner(Controls.HTMLBanner__);
banner.SetMainTitle("_Cancel those items");
banner.SetSubTitle("_Cancel those items subtitle");
Controls.LineItems__.PRRUIDEX__.Hide(true);
Controls.LineItems__.RequesterDN__.Hide(true);
Controls.LineItems__.SetWidth("100%");
Controls.LineItems__.SetExtendableColumn("Description__");
Controls.LineItems__.HideTableRowMenu(true);
Controls.LineItems__.HideTopNavigation(true);
Controls.LineItems__.HideBottomNavigation(true);
Controls.LineItems__.HideTableRowDelete(false);
Controls.LineItems__.HideTableRowAdd(true);
Controls.LineItems__.SetAtLeastOneLine(false);
Sys.Parameters.GetInstance("P2P").IsReady(() => {
    Lib.P2P.InitItemTypeControl(Controls.LineItems__.ItemType__);
});
Controls.Comment__.SetError("");
Controls.Comment__.Focus();
/** ************** **/
/** Global Helpers **/
/** ************** **/
const confirmCancelItemsButton = (function () {
    function SetDisabledState() {
        Controls.ConfirmCancelItems.SetDisabled(Controls.LineItems__.GetItemCount() == 0 || Sys.Helpers.IsEmpty(Controls.Comment__.GetValue()));
    }
    return {
        SetDisabledState: SetDisabledState
    };
})();
Controls.LineItems__.OnDeleteItem = function ( /*item, index*/) {
    confirmCancelItemsButton.SetDisabledState();
};
Controls.Comment__.OnChange = function () {
    confirmCancelItemsButton.SetDisabledState();
};
Controls.ConfirmCancelItems.OnClick = function () {
    if (Process.ShowFirstError() === null) {
        ProcessInstance.ApproveAsynchronous("Cancel_PRItems");
    }
};
Controls.LineItems__.OnRefreshRow = function (index) {
    let row = Controls.LineItems__.GetRow(index);
    const isAmountBase = Lib.Purchasing.Items.IsAmountBasedItem(row.GetItem());
    row.CancelableQuantity__.Hide(isAmountBase);
    row.CancelableAmount__.Hide(!isAmountBase);
};
let nbrItemsAmountBased = 0;
let nbrItemsQuantityBased = 0;
let index = 0;
Sys.Helpers.Data.ForEachTableItem("LineItems__", function (item) {
    Lib.Purchasing.Items.IsAmountBasedItem(item) ? ++nbrItemsAmountBased : ++nbrItemsQuantityBased;
    ++index;
});
Controls.LineItems__.CancelableAmount__.Hide(nbrItemsAmountBased == 0);
Controls.LineItems__.CancelableQuantity__.Hide(nbrItemsQuantityBased == 0);
for (let i = 0; i < index; i++) {
    Controls.LineItems__.OnRefreshRow(i);
}
const deprecatedControls = ["Actions", "Spacer", "Spacer_line__", "Spacer_line2__"].map((name) => Controls[name]);
deprecatedControls.forEach(function (deprecatedControl) {
    if (deprecatedControl) {
        deprecatedControl.Hide(true);
    }
});
confirmCancelItemsButton.SetDisabledState();
//# sourceMappingURL=customscript.js.map

